/* Mandatory rule to prevent style overriding hidden attribute */
[hidden] {
  display: none !important;
}

:root {
  --color-bg: #201c2b;
  --color-card: #2c273e;
  --color-card-border: #463e63;
  --color-text-main: #f4f3fa;
  --color-text-sub: #a49fc4;
  --color-green-healthy: #38b764;
  --color-green-dark: #257953;
  --color-accent-blue: #3b5dc9;
  --color-accent-blue-hover: #4e73e6;
  --color-accent-blue-active: #2d4599;
  --color-alert-wilt: #d95763;
  --color-alert-bg: #ffe478;
  --color-meter-bg: #191624;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  background-color: var(--color-bg);
  color: var(--color-text-main);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 1rem;
}

.app-container {
  width: 100%;
  max-width: 420px;
  min-width: 320px;
}

.card {
  background-color: var(--color-card);
  border: 4px solid var(--color-card-border);
  border-radius: 12px;
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
}

.card-header {
  text-align: center;
}

.title {
  font-size: 1.5rem;
  font-weight: 700;
  color: #fff;
  letter-spacing: 0.5px;
}

.subtitle {
  font-size: 0.95rem;
  color: var(--color-text-sub);
}

.canvas-wrapper {
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: var(--color-meter-bg);
  border: 3px solid var(--color-card-border);
  border-radius: 8px;
  padding: 1rem;
}

#plantCanvas {
  width: 192px;
  height: 192px;
  image-rendering: pixelated;
  image-rendering: crisp-edges;
  background: transparent;
}

.thirsty-badge {
  position: absolute;
  top: 12px;
  right: 12px;
  background-color: var(--color-alert-wilt);
  color: #fff;
  font-size: 0.85rem;
  font-weight: bold;
  padding: 0.25rem 0.6rem;
  border-radius: 4px;
  border: 2px solid #ffffff;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.3);
  animation: pulse 1s infinite alternate ease-in-out;
}

@keyframes pulse {
  from {
    transform: scale(0.96);
  }
  to {
    transform: scale(1.04);
  }
}

.status-section {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.meter-header {
  display: flex;
  justify-content: space-between;
  font-size: 0.95rem;
}

.meter-label {
  font-weight: 600;
  color: var(--color-text-sub);
}

.meter-value {
  font-weight: 700;
  color: var(--color-text-main);
}

.meter-track {
  height: 22px;
  background-color: var(--color-meter-bg);
  border: 2px solid var(--color-card-border);
  border-radius: 6px;
  overflow: hidden;
  position: relative;
}

.meter-fill {
  height: 100%;
  background-color: var(--color-green-healthy);
  transition: width 0.15s ease, background-color 0.3s ease;
}

.meter-fill.wilted {
  background-color: var(--color-alert-wilt);
}

.action-section {
  display: flex;
  justify-content: center;
}

.action-btn {
  width: 100%;
  padding: 0.85rem 1.25rem;
  font-size: 1.1rem;
  font-weight: 700;
  color: #ffffff;
  background-color: var(--color-accent-blue);
  border: 2px solid #6b8cff;
  border-radius: 8px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  transition: background-color 0.15s ease, transform 0.1s ease, box-shadow 0.15s ease;
}

.action-btn:hover {
  background-color: var(--color-accent-blue-hover);
  box-shadow: 0 4px 12px rgba(59, 93, 201, 0.4);
}

.action-btn:focus-visible {
  outline: 3px solid #ffe478;
  outline-offset: 2px;
}

.action-btn:active {
  background-color: var(--color-accent-blue-active);
  transform: translateY(2px);
}

.card-footer {
  border-top: 1px solid var(--color-card-border);
  padding-top: 0.75rem;
  display: flex;
  justify-content: center;
}

.counter-box {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 1rem;
  color: var(--color-text-sub);
}

.counter-value {
  font-size: 1.2rem;
  color: var(--color-alert-bg);
}

document.addEventListener('DOMContentLoaded', () => {
  const DURATION_MS = 2 * 60 * 1000; // 2 minutes in milliseconds
  const WILT_THRESHOLD = 30;

  // Elements
  const canvas = document.getElementById('plantCanvas');
  const ctx = canvas.getContext('2d');
  const moistureFill = document.getElementById('moistureFill');
  const moistureMeter = document.getElementById('moistureMeter');
  const moisturePercent = document.getElementById('moisturePercent');
  const thirstyBadge = document.getElementById('thirstyBadge');
  const waterBtn = document.getElementById('waterBtn');
  const waterCountElem = document.getElementById('waterCount');

  // State
  let moisture = 100; // 0 to 100
  let timesWatered = 0;
  let lastTimestamp = performance.now();

  // Canvas configuration
  ctx.imageSmoothingEnabled = false;

  function drawPixel(x, y, color, size = 4) {
    ctx.fillStyle = color;
    ctx.fillRect(x * size, y * size, size, size);
  }

  function renderPlant(isWilted) {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    const pSize = 4; // 32x32 pixel grid within 128x128 canvas

    // Colors
    const potRim = '#d27d2d';
    const potBody = '#a6541d';
    const potDark = '#68320e';
    const dirt = '#4d2b14';
    const stemColor = isWilted ? '#8a7d36' : '#257953';
    const leafMain = isWilted ? '#a89437' : '#38b764';
    const leafDark = isWilted ? '#6a5e23' : '#1d5a39';
    const leafHighlight = isWilted ? '#cfba5b' : '#68e08d';

    // 1. Draw Pot (from row 21 to 30)
    // Pot Rim (rows 21-22, cols 8 to 23)
    for (let r = 21; r <= 22; r++) {
      for (let c = 8; c <= 23; c++) {
        let color = potRim;
        if (r === 22 && (c === 8 || c === 23)) color = potDark;
        drawPixel(c, r, color, pSize);
      }
    }
    // Soil top
    for (let c = 10; c <= 21; c++) {
      drawPixel(c, 21, dirt, pSize);
    }

    // Pot Body tapered (rows 23-29)
    for (let r = 23; r <= 29; r++) {
      const indent = Math.floor((r - 23) / 2.5);
      const startC = 10 + indent;
      const endC = 21 - indent;
      for (let c = startC; c <= endC; c++) {
        let color = potBody;
        if (c === startC) color = potRim;
        if (c >= endC - 1) color = potDark;
        drawPixel(c, r, color, pSize);
      }
    }
    // Pot base (row 30)
    for (let c = 12; c <= 19; c++) {
      drawPixel(c, 30, potDark, pSize);
    }

    // 2. Draw Plant (Stem and Leaves)
    if (!isWilted) {
      // Healthy upright stem
      for (let r = 12; r <= 20; r++) {
        drawPixel(15, r, stemColor, pSize);
        drawPixel(16, r, leafDark, pSize);
      }

      // Left leaf (healthy)
      const leftLeaf = [
        { c: 14, r: 16 }, { c: 13, r: 15 }, { c: 12, r: 15 },
        { c: 11, r: 14 }, { c: 12, r: 14 }, { c: 13, r: 14 },
        { c: 10, r: 13 }, { c: 11, r: 13 }, { c: 12, r: 13 },
        { c: 11, r: 12 }, { c: 10, r: 12 }
      ];
      leftLeaf.forEach(p => drawPixel(p.c, p.r, leafMain, pSize));
      drawPixel(11, 13, leafHighlight, pSize);
      drawPixel(13, 16, leafDark, pSize);

      // Right leaf (healthy)
      const rightLeaf = [
        { c: 17, r: 15 }, { c: 18, r: 14 }, { c: 19, r: 14 },
        { c: 18, r: 13 }, { c: 19, r: 13 }, { c: 20, r: 13 },
        { c: 20, r: 12 }, { c: 21, r: 12 }, { c: 20, r: 11 }
      ];
      rightLeaf.forEach(p => drawPixel(p.c, p.r, leafMain, pSize));
      drawPixel(19, 13, leafHighlight, pSize);
      drawPixel(17, 16, leafDark, pSize);

      // Top sprout bud
      drawPixel(15, 11, leafHighlight, pSize);
      drawPixel(16, 11, leafMain, pSize);
      drawPixel(15, 10, leafHighlight, pSize);
      drawPixel(16, 10, leafMain, pSize);
    } else {
      // Wilted stem curving and drooping right & down
      const wiltedStem = [
        { c: 15, r: 20 }, { c: 15, r: 19 },
        { c: 16, r: 18 }, { c: 17, r: 17 },
        { c: 18, r: 17 }, { c: 19, r: 18 },
        { c: 20, r: 19 }, { c: 20, r: 20 }
      ];
      wiltedStem.forEach(p => drawPixel(p.c, p.r, stemColor, pSize));

      // Drooped Left Leaf
      const droopLeft = [
        { c: 14, r: 18 }, { c: 13, r: 19 }, { c: 12, r: 20 },
        { c: 11, r: 20 }, { c: 11, r: 21 }
      ];
      droopLeft.forEach(p => drawPixel(p.c, p.r, leafMain, pSize));
      drawPixel(12, 20, leafDark, pSize);

      // Drooped Right / Main Branch Leaves
      const droopRight = [
        { c: 21, r: 20 }, { c: 22, r: 21 }, { c: 22, r: 22 },
        { c: 20, r: 21 }, { c: 21, r: 22 }, { c: 21, r: 23 }
      ];
      droopRight.forEach(p => drawPixel(p.c, p.r, leafMain, pSize));
      drawPixel(22, 21, leafHighlight, pSize);
      drawPixel(21, 23, leafDark, pSize);
    }
  }

  function updateUI() {
    const roundedMoisture = Math.max(0, Math.min(100, Math.round(moisture)));
    const isWilted = roundedMoisture < WILT_THRESHOLD;

    // Progress bar and labels
    moistureFill.style.width = `${moisture}%`;
    moistureMeter.setAttribute('aria-valuenow', roundedMoisture.toString());
    moisturePercent.textContent = `${roundedMoisture}%`;

    if (isWilted) {
      moistureFill.classList.add('wilted');
      thirstyBadge.removeAttribute('hidden');
    } else {
      moistureFill.classList.remove('wilted');
      thirstyBadge.setAttribute('hidden', '');
    }

    renderPlant(isWilted);
  }

  function tick(currentTimestamp) {
    const delta = currentTimestamp - lastTimestamp;
    lastTimestamp = currentTimestamp;

    // Drain moisture according to elapsed time (100% per DURATION_MS)
    if (moisture > 0) {
      const drainRate = (100 / DURATION_MS) * delta;
      moisture = Math.max(0, moisture - drainRate);
      updateUI();
    }

    requestAnimationFrame(tick);
  }

  // Water button event handler
  waterBtn.addEventListener('click', () => {
    moisture = 100;
    timesWatered += 1;
    waterCountElem.textContent = timesWatered.toString();
    updateUI();
  });

  // Initial render & loop launch
  updateUI();
  requestAnimationFrame(tick);
});
